using System; using System.Configuration; using System.Data.SqlClient;
public partial class AddCourse : System.Web.UI.Page { protected void Button1_Click(object sender, EventArgs e){ if(string.IsNullOrWhiteSpace(TextBox1.Text)){Label1.Text="Enter a course name.";return;} using(var con=new SqlConnection(ConfigurationManager.ConnectionStrings["ABC"].ConnectionString)){con.Open();using(var cmd=new SqlCommand("INSERT INTO AddCourse(CourseName,Precap) VALUES(@n,@d)",con)){cmd.Parameters.AddWithValue("@n",TextBox1.Text.Trim());cmd.Parameters.AddWithValue("@d",TextBox3.Text.Trim());cmd.ExecuteNonQuery();}} TextBox1.Text="";TextBox3.Text="";Label1.Text="Course added successfully.";} }